int do_run(gchar* command, gchar* file) {
	_cleanup_g_free_ gchar* cmd = NULL;
	int retval=0;

	if(command && *command) {
		cmd = g_strdup_printf(command, file);
		retval=system(cmd);
	}
	return retval;
}

/**
 * Open the copy-on-write diff file for this connection.
 *
 * Writes to a copy-on-write export are redirected to a diff file
 * which is private to this connection, so that the master file is
 * left untouched. If the cowdir option is set, the diff file is
 * created there; otherwise it is created in the same directory as
 * the master file. The PID is part of the name so that concurrent
 * connections to the same export don't clobber each other's diffs.
 *
 * @param client the client for which to open the diff file
 * @return true on success, false on failure
 **/
static bool open_diff(CLIENT* client) {
	gchar* diffname;
	int fhandle;

	if(client->server->cowdir) {
		_cleanup_g_free_ gchar* base = g_path_get_basename(client->exportname);
		diffname = g_strdup_printf("%s/%s-%d.diff", client->server->cowdir, base, (int)getpid());
	} else {
		diffname = g_strdup_printf("%s-%d.diff", client->exportname, (int)getpid());
	}
	fhandle = open(diffname, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if(fhandle < 0) {
		err_nonfatal("Could not open copy-on-write diff file: %m");
		g_free(diffname);
		return false;
	}
	if(client->server->flags & F_SPARSE) {
		/* Use a sparse file the size of the export, so that the
		 * data can be written at the same offset as in the export */
		if(ftruncate(fhandle, client->exportsize) < 0) {
			err_nonfatal("Could not expand copy-on-write diff file: %m");
			close(fhandle);
			unlink(diffname);
			g_free(diffname);
			return false;
		}
	}
	client->difffile = fhandle;
	client->diffname = diffname;
	client->diffmap = g_hash_table_new_full(g_int64_hash, g_int64_equal, g_free, g_free);
	msg(LOG_INFO, "Using copy-on-write diff file %s", diffname);
	return true;
}

/**
 * Clean up the copy-on-write diff file of this connection: the
 * written data is discarded, and the master file is left as it was.
 *
 * @param client the client whose diff file should be cleaned up
 **/
static void close_diff(CLIENT* client) {
	if(client->diffmap) {
		g_hash_table_destroy(client->diffmap);
		client->diffmap = NULL;
	}
	if(client->difffile >= 0) {
		close(client->difffile);
		client->difffile = -1;
	}
	if(client->diffname) {
		unlink(client->diffname);
		g_free(client->diffname);
		client->diffname = NULL;
	}
}

static inline void finalize_client(CLIENT* client) {
	g_thread_pool_free(tpool, FALSE, TRUE);
	close_diff(client);
	do_run(client->server->postrun, client->exportname);
	if(client->transactionlogfd != -1)
		cleanup_transactionlog(client);

	serve_dec_ref(client->server);
}

