/**
 * Read an amount of bytes at a given offset from the master file(s)
 * of the export, ignoring any copy-on-write diff file. This abstracts
 * the read-side of the multiple files option.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t masterexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	DEBUG("(READ from fd %d offset %llu len %u), ", fhandle, (long long unsigned int)foffset, (unsigned int)len);

	retval = pread(fhandle, buf, len, foffset);
        if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}

/**
 * Find the offset at which the given page of the export is stored in
 * the copy-on-write diff file.
 *
 * @param client The client we're serving for
 * @param pageno The page number (in DIFFPAGESIZE chunks) to look up
 * @return A pointer to the offset in the diff file, or NULL if the
 * page has not been written during this connection
 **/
static off_t *diff_page_lookup(CLIENT *client, off_t pageno) {
	gint64 key = pageno;

	return g_hash_table_lookup(client->diffmap, &key);
}

/**
 * Allocate a slot in the copy-on-write diff file for a page that has
 * not been written before. With sparse_cow, the page is stored at the
 * same offset as in the export; otherwise, every newly written page
 * is mapped to the end of the diff file.
 *
 * @param client The client we're serving for
 * @param pageno The page number (in DIFFPAGESIZE chunks) to allocate
 * @return The offset in the diff file where the page is to be stored,
 * or -1 in case of an error
 **/
static off_t diff_page_alloc(CLIENT *client, off_t pageno) {
	gint64 *key;
	off_t *doff;
