static ssize_t cowexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t done = 0;

	pthread_mutex_lock(&client->diff_lock);
	while(done < len) {
		off_t pos = a + done;
		off_t pagestart = (pos / DIFFPAGESIZE) * DIFFPAGESIZE;
		off_t chunk = pagestart + DIFFPAGESIZE - pos;
