 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t cowexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t done = 0;

	pthread_mutex_lock(&client->diff_lock);
	while(done < len) {
		off_t pos = a + done;
		off_t pagestart = (pos / DIFFPAGESIZE) * DIFFPAGESIZE;
		off_t chunk = pagestart + DIFFPAGESIZE - pos;
		off_t *doff = diff_page_lookup(client, pos / DIFFPAGESIZE);
		ssize_t res;

		if(chunk > (off_t)(len - done))
			chunk = len - done;
		DEBUG("(COW READ offset %llu len %u), ", (unsigned long long)pos, (unsigned int)chunk);
		if(doff) {
			res = pread(client->difffile, buf + done, chunk,
					*doff + (pos - pagestart));
		} else {
			res = masterexpread(pos, buf + done, chunk, client);
		}
		if(res < 0) {
			pthread_mutex_unlock(&client->diff_lock);
			return -1;
		}
		if((size_t)res < (size_t)chunk) {
			/* end of file, e.g. on the last page of an export
			 * whose size is not a multiple of DIFFPAGESIZE */
			memset(buf + done + res, 0, chunk - res);
			res = chunk;
		}
		done += res;
	}
	pthread_mutex_unlock(&client->diff_lock);
	return done;
}

/**
 * Write an amount of bytes at a given offset to the copy-on-write
 * diff file rather than to the master file. Pages that are only
 * partially overwritten are first filled with their current contents
 * from the diff file, or from the master file if the page has not
 * been written during this connection, so that the other data in the
 * page is preserved.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, -1 in case of an error
 **/
static int cowexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	char pagebuf[DIFFPAGESIZE];
	size_t done = 0;
	int retval = -1;

	pthread_mutex_lock(&client->diff_lock);
	while(done < len) {
		off_t pos = a + done;
		off_t pageno = pos / DIFFPAGESIZE;
		off_t pagestart = pageno * DIFFPAGESIZE;
		off_t chunk = pagestart + DIFFPAGESIZE - pos;
		off_t *slot = diff_page_lookup(client, pageno);
		off_t doff;
		char *data;
		ssize_t res;

		if(chunk > (off_t)(len - done))
			chunk = len - done;
		if(slot) {
			doff = *slot;
		} else if((doff = diff_page_alloc(client, pageno)) < 0) {
			goto out;
		}
		DEBUG("(COW WRITE to diff offset %llu len %u), ", (unsigned long long)doff, (unsigned int)chunk);
		if(chunk == DIFFPAGESIZE) {
			/* the whole page is overwritten, so its current
			 * contents don't need to be preserved */
			data = buf + done;
		} else {
			if(slot) {
				res = pread(client->difffile, pagebuf,
						DIFFPAGESIZE, doff);
			} else {
				res = masterexpread(pagestart, pagebuf,
						DIFFPAGESIZE, client);
			}
			if(res < 0)
				goto out;
			if(res < DIFFPAGESIZE)
				memset(pagebuf + res, 0, DIFFPAGESIZE - res);
			memcpy(pagebuf + (pos - pagestart), buf + done, chunk);
			data = pagebuf;
		}
		size_t wdone = 0;
		while(wdone < (size_t)DIFFPAGESIZE) {
			res = pwrite(client->difffile, data + wdone,
					DIFFPAGESIZE - wdone, doff + wdone);
			if(res < 0)
				goto out;
			wdone += res;
		}
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	retval = 0;
out:
	pthread_mutex_unlock(&client->diff_lock);
	return retval;
}

