			} else {
				res = masterexpread(pagestart, pagebuf, DIFFPAGESIZE, client);
			}
			if(res < 0)
				goto out;
			if(res < DIFFPAGESIZE)
				memset(pagebuf + res, 0, DIFFPAGESIZE - res);
			memcpy(pagebuf + (pos - pagestart), buf + done, chunk);
			data = pagebuf;
